mapper.select:
SELECT pro.P_Id AS pId, pro.P_Name AS pName, COUNT(DISTINCT CASE WHEN tdc.hf_Hg_Flag = '01' THEN tdc.tdc_Id END) AS questionSum FROM Drawing_Management_Catalogue mn LEFT JOIN pre_project pro ON pro.P_Id = mn.p_id LEFT JOIN task_distribution td ON td.dm_Id = mn.dm_Id LEFT JOIN task_distribution_check tdc ON tdc.td_Id = td.td_Id WHERE 1=1 AND (mn.del_flag <> '02' or mn.del_Flag is null)
and mn.Te_Id = #{params.teId}
AND mn.p_Id = #{params.pId}
AND pro.p_Name LIKE concat('%', #{params.pName}, '%')
AND td.dm_Region_Name LIKE concat('%', #{params.taskName}, '%')
AND tdc.check_Person_Uid = #{params.userTaskId}
AND mn.dm_Code = LIKE concat('%', #{params.dmCode}, '%')
AND mn.dm_Parent_Id = #{params.dmParentId}
AND mn.dm_Drawing = #{params.dmDrawing}
GROUP BY pro.P_Id, pro.P_Name
